}
.cart-item-info { flex: 1; min-width: 0; }
.cart-item-name { font-size: .9rem; font-weight: 600; }
.cart-item-price { font-size: .875rem; color: var(--color-accent); font-weight: 700; }
.cart-item-remove {
  border: none; background: transparent;
  color: var(--color-text-muted); font-size: .9rem;
