:root {
  --color-brand:        #1a1a2e;
  --color-accent:       #e94560;
  --color-accent-hover: #c73652;
  --color-surface:      #ffffff;
  --color-surface-2:    #f5f5f7;
  --color-surface-3:    #ebebf0;
  --color-text:         #1a1a2e;
  --color-text-muted:   #6b6b80;
  --color-border:       #dcdce4;
  --color-success:      #0f9d58;
  --color-deal:         #ff6b35;

  --radius-sm:   6px;
  --radius-md:   12px;
  --radius-lg:   20px;
  --radius-full: 9999px;

  --shadow-card: 0 2px 12px rgba(0,0,0,.08), 0 0 1px rgba(0,0,0,.06);
  --shadow-card-hover: 0 8px 32px rgba(0,0,0,.14), 0 0 1px rgba(0,0,0,.08);

  --transition: 220ms ease;

  --max-w: 1280px;
  --gap:   clamp(16px, 2.5vw, 32px);
}

/* ─── Reset / Base ───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: var(--color-surface);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a   { color: inherit; text-decoration: none; }
ul  { list-style: none; }
button { cursor: pointer; font: inherit; }

/* ─── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 1000;
  padding: .5rem 1rem;
  background: var(--color-brand);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ─── Utilities ──────────────────────────────────────────────── */
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.container {
  max-width: var(--max-w);
  margin-inline: auto;
  padding-inline: var(--gap);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.75rem;
  flex-wrap: wrap;
}
.section-header h2 {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
}
.view-all {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  white-space: nowrap;
  border-radius: var(--radius-sm);
  padding: .25rem .5rem;
  transition: color var(--transition), background var(--transition);
}
.view-all:hover { color: var(--color-accent-hover); background: rgba(233,69,96,.07); }
.view-all:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ─── Header / Nav ───────────────────────────────────────────── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  padding-block: .875rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -.04em;
  color: var(--color-brand);
  white-space: nowrap;
  border-radius: var(--radius-sm);
  padding: .25rem .5rem;
}
.logo:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.logo-mark {
  width: 32px; height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  color: #fff;
  font-size: .9rem;
}

/* Main nav */
.main-nav { display: flex; align-items: center; gap: .25rem; }
.main-nav a {
  padding: .5rem .75rem;
  font-size: .9375rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  white-space: nowrap;
}
.main-nav a:hover,
.main-nav a[aria-current="page"] { color: var(--color-text); background: var(--color-surface-2); }
.main-nav a:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; }

/* Search form */
.search-form { display: flex; align-items: center; gap: .5rem; }
.search-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}
.search-wrapper svg {
  position: absolute;
  left: .75rem;
  color: var(--color-text-muted);
  pointer-events: none;
}
.search-input {
  height: 38px;
  padding: 0 1rem 0 2.5rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: .875rem;
  background: var(--color-surface-2);
  color: var(--color-text);
  width: clamp(140px, 18vw, 220px);
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
}
.search-input::placeholder { color: var(--color-text-muted); }
.search-input:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(233,69,96,.2);
  background: #fff;
}

.icon-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px; height: 40px;
  border: none;
  background: transparent;
  border-radius: var(--radius-md);
  color: var(--color-text);
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover  { background: var(--color-surface-2); }
.icon-btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

.cart-badge {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 16px; height: 16px;
  padding: 0 4px;
  background: var(--color-accent);
  color: #fff;
  font-size: .625rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  display: grid;
  place-items: center;
  line-height: 1;
  pointer-events: none;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ─── Hero ───────────────────────────────────────────────────── */
.hero {
  padding-block: clamp(48px, 8vw, 96px);
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 60%, #0f3460 100%);
  color: #fff;
  overflow: hidden;
  position: relative;
}
.hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 80% 50%, rgba(233,69,96,.18) 0%, transparent 70%);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(32px, 5vw, 64px);
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .8125rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: rgba(233,69,96,.15);
  border: 1px solid rgba(233,69,96,.3);
  border-radius: var(--radius-full);
  padding: .3rem .8rem;
  margin-bottom: 1.25rem;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.1;
  margin-bottom: 1.25rem;
}
.hero h1 em {
  font-style: normal;
  color: var(--color-accent);
}

.hero-description {
  font-size: clamp(.9375rem, 1.5vw, 1.125rem);
  color: rgba(255,255,255,.7);
  max-width: 44ch;
  margin-bottom: 2rem;
}

.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-full);
  font-size: .9375rem;
  font-weight: 600;
  border: 2px solid transparent;
  transition: background var(--transition), color var(--transition), border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.btn:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 3px; }
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.btn-primary:hover { background: var(--color-accent-hover); box-shadow: 0 4px 20px rgba(233,69,96,.4); }

.btn-ghost {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,.35);
}
.btn-ghost:hover { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.6); }

/* Hero visual */
.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 1;
}

.hero-product-showcase {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  width: min(420px, 100%);
}
.showcase-card {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-lg);
  padding: 1.25rem;
  backdrop-filter: blur(8px);
  transition: transform var(--transition), background var(--transition);
}
.showcase-card:hover { transform: translateY(-4px); background: rgba(255,255,255,.11); }
.showcase-card-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  background: rgba(255,255,255,.08);
  display: grid;
  place-items: center;
  font-size: 2.5rem;
  margin-bottom: .75rem;
}
.showcase-card-name {
  font-size: .8125rem;
  font-weight: 600;
  color: rgba(255,255,255,.9);
  margin-bottom: .2rem;
}
.showcase-card-price {
  font-size: .75rem;
  color: var(--color-accent);
  font-weight: 700;
}

/* Hero stats */
.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 1.75rem;
  border-top: 1px solid rgba(255,255,255,.12);
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: #fff;
}
.stat-label { font-size: .75rem; color: rgba(255,255,255,.5); margin-top: .1rem; }

/* ─── Category Pills ─────────────────────────────────────────── */
.categories-section { padding-block: 2.5rem; }
.categories-list {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: .25rem;
}
.categories-list::-webkit-scrollbar { display: none; }

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .55rem 1.1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: .875rem;
  font-weight: 500;
  background: var(--color-surface);
  color: var(--color-text);
  white-space: nowrap;
  transition: border-color var(--transition), background var(--transition), color var(--transition);
}
.category-pill:hover,
.category-pill[aria-current="true"] {
  border-color: var(--color-accent);
  background: rgba(233,69,96,.06);
  color: var(--color-accent);
}
.category-pill:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.category-pill span { font-size: 1rem; }

/* ─── Product Grid ───────────────────────────────────────────── */
.products-section { padding-block: clamp(40px, 6vw, 72px); }

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr));
  gap: var(--gap);
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: box-shadow var(--transition), transform var(--transition);
}
.product-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-3px); }

.product-image-wrap {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--color-surface-2);
  display: grid;
  place-items: center;
  overflow: hidden;
}
.product-emoji {
  font-size: 4rem;
  line-height: 1;
  transition: transform var(--transition);
}
.product-card:hover .product-emoji { transform: scale(1.1); }

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .25rem .6rem;
  border-radius: var(--radius-full);
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .03em;
  text-transform: uppercase;
}
.badge-new   { background: var(--color-brand); color: #fff; }
.badge-sale  { background: var(--color-accent); color: #fff; }
.badge-hot   { background: var(--color-deal);   color: #fff; }

.product-wishlist {
  position: absolute;
  top: .65rem;
  right: .65rem;
  width: 34px; height: 34px;
  display: grid;
  place-items: center;
  background: rgba(255,255,255,.9);
  border: none;
  border-radius: 50%;
  color: var(--color-text-muted);
  box-shadow: 0 1px 4px rgba(0,0,0,.12);
  transition: background var(--transition), color var(--transition), transform var(--transition);
}
.product-wishlist:hover { background: #fff; color: var(--color-accent); transform: scale(1.1); }
.product-wishlist:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.product-wishlist[aria-pressed="true"] { color: var(--color-accent); }
.product-wishlist[aria-pressed="true"] svg { fill: var(--color-accent); }

.product-info {
  padding: 1rem 1.1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
  flex: 1;
}
.product-category {
  font-size: .6875rem;
  font-weight: 600;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: -.01em;
  color: var(--color-text);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}
.product-rating {
  display: flex;
  align-items: center;
  gap: .35rem;
  font-size: .8125rem;
}
.stars { color: #f5a623; letter-spacing: .04em; }
.rating-count { color: var(--color-text-muted); }

.product-pricing {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-top: auto;
  padding-top: .5rem;
}
.price-current {
  font-size: 1.1875rem;
  font-weight: 700;
  letter-spacing: -.02em;
}
.price-original {
  font-size: .875rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.price-discount {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-success);
  background: rgba(15,157,88,.1);
  padding: .15rem .45rem;
  border-radius: var(--radius-full);
}

.btn-add-cart {
  margin-top: .75rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  width: 100%;
  padding: .65rem 1rem;
  background: var(--color-brand);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  font-size: .9rem;
  font-weight: 600;
  transition: background var(--transition), box-shadow var(--transition), transform var(--transition);
}
.btn-add-cart:hover  { background: #2a2a4a; box-shadow: 0 4px 16px rgba(26,26,46,.3); }
.btn-add-cart:active { transform: scale(.97); }
.btn-add-cart:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.btn-add-cart.added  { background: var(--color-success); }

/* ─── Deals Section ──────────────────────────────────────────── */
.deals-section {
  padding-block: clamp(40px, 6vw, 72px);
  background: var(--color-surface-2);
}

.deals-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1.75rem;
}
.deals-header h2 {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
}
.countdown {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-left: auto;
}
.countdown-label {
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-text-muted);
}
.countdown-timer {
  display: flex;
  align-items: center;
  gap: .25rem;
}
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 40px;
  background: var(--color-brand);
  color: #fff;
  border-radius: var(--radius-sm);
  padding: .35rem .5rem;
}
.countdown-num {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1;
}
.countdown-sep {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-muted);
}
.countdown-lbl {
  font-size: .55rem;
  letter-spacing: .06em;
  text-transform: uppercase;
  opacity: .75;
  margin-top: .1rem;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr));
  gap: var(--gap);
}

.deal-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  gap: 1rem;
  padding: 1.25rem;
  box-shadow: var(--shadow-card);
  border: 1px solid var(--color-border);
  transition: box-shadow var(--transition), transform var(--transition);
  align-items: center;
}
.deal-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-2px); }

.deal-image {
  flex-shrink: 0;
  width: 90px; height: 90px;
  background: var(--color-surface-2);
  border-radius: var(--radius-md);
  display: grid;
  place-items: center;
  font-size: 2.5rem;
}
.deal-info { flex: 1; min-width: 0; }
.deal-category {
  font-size: .6875rem;
  font-weight: 600;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--color-deal);
  margin-bottom: .2rem;
}
.deal-name {
  font-size: .9375rem;
  font-weight: 600;
  margin-bottom: .35rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.deal-progress {
  margin-bottom: .5rem;
}
.progress-bar {
  height: 5px;
  background: var(--color-surface-3);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: .3rem;
}
.progress-fill {
  height: 100%;
  background: var(--color-deal);
  border-radius: var(--radius-full);
  transition: width 1s ease;
}
.progress-label { font-size: .7rem; color: var(--color-text-muted); }
.deal-pricing {
  display: flex;
  align-items: baseline;
  gap: .5rem;
}
.deal-price {
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--color-accent);
}
.deal-original {
  font-size: .8125rem;
  color: var(--color-text-muted);
  text-decoration: line-through;
}
.deal-save {
  font-size: .75rem;
  font-weight: 700;
  color: var(--color-success);
}

/* ─── Banner Strip ───────────────────────────────────────────── */
.promo-banner {
  background: var(--color-accent);
  color: #fff;
  padding-block: 1rem;
}
.promo-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  text-align: center;
}
.promo-item {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .9rem;
  font-weight: 500;
}
.promo-item strong { font-weight: 700; }
.promo-divider { opacity: .4; }

/* ─── Editorial / Blog ───────────────────────────────────────── */
.editorial-section { padding-block: clamp(40px, 6vw, 72px); }

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: var(--gap);
}
.editorial-grid .card-featured {
  grid-column: 1 / 3;
}

@media (max-width: 900px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid .card-featured { grid-column: 1 / -1; }
}
@media (max-width: 600px) {
  .editorial-grid { grid-template-columns: 1fr; }
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-3px); }

.editorial-card-img {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, var(--color-brand) 0%, #0f3460 100%);
  display: grid;
  place-items: center;
  font-size: 3.5rem;
  overflow: hidden;
  position: relative;
}
.card-featured .editorial-card-img { aspect-ratio: 21/9; font-size: 5rem; }

.editorial-tag {
  position: absolute;
  top: .75rem; left: .75rem;
  padding: .25rem .65rem;
  background: rgba(0,0,0,.55);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  border-radius: var(--radius-full);
  backdrop-filter: blur(4px);
}

.editorial-body {
  padding: 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}
.editorial-meta {
  font-size: .75rem;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: .5rem;
}
.editorial-dot { opacity: .4; }
.editorial-title {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -.015em;
  line-height: 1.3;
}
.card-featured .editorial-title { font-size: clamp(1.1rem, 2vw, 1.35rem); }
.editorial-excerpt {
  font-size: .875rem;
  color: var(--color-text-muted);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  line-height: 1.55;
}
.editorial-link {
  margin-top: auto;
  padding-top: .75rem;
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  border-radius: var(--radius-sm);
  transition: gap var(--transition), color var(--transition);
}
.editorial-link:hover { gap: .5rem; color: var(--color-accent-hover); }
.editorial-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }

/* ─── Newsletter ─────────────────────────────────────────────── */
.newsletter-section {
  padding-block: clamp(40px, 6vw, 72px);
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #fff;
  text-align: center;
}
.newsletter-inner { max-width: 560px; margin-inline: auto; }
.newsletter-icon { font-size: 2.5rem; margin-bottom: .75rem; }
.newsletter-section h2 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800;
