+  font-weight: 600;
+  color: rgba(255,255,255,.9);
+  margin-bottom: .2rem;
+}
+.showcase-card-price {
+  font-size: .75rem;
+  color: var(--color-accent);
+  font-weight: 700;
+}
+
+/* Hero stats */
+.hero-stats {
+  display: flex;
+  gap: 2rem;
+  margin-top: 2.5rem;
+  padding-top: 1.75rem;
+  border-top: 1px solid rgba(255,255,255,.12);
+  flex-wrap: wrap;
