+}
+.product-card:hover .product-emoji { transform: scale(1.1); }
+
+.product-badge {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  padding: .25rem .6rem;
+  border-radius: var(--radius-full);
+  font-size: .6875rem;
+  font-weight: 700;
+  letter-spacing: .03em;
+  text-transform: uppercase;
+}
+.badge-new   { background: var(--color-brand); color: #fff; }
+.badge-sale  { background: var(--color-accent); color: #fff; }
+.badge-hot   { background: var(--color-deal);   color: #fff; }
+
+.product-wishlist {
+  position: absolute;
+  top: .65rem;
+  right: .65rem;
+  width: 34px; height: 34px;
+  display: grid;
+  place-items: center;
+  background: rgba(255,255,255,.9);
+  border: none;
+  border-radius: 50%;
+  color: var(--color-text-muted);
+  box-shadow: 0 1px 4px rgba(0,0,0,.12);
+  transition: background var(--transition), color var(--transition), transform var(--transition);
+}
+.product-wishlist:hover { background: #fff; color: var(--color-accent); transform: scale(1.1); }
+.product-wishlist:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
+.product-wishlist[aria-pressed="true"] { color: var(--color-accent); }
+.product-wishlist[aria-pressed="true"] svg { fill: var(--color-accent); }
+
+.product-info {
+  padding: 1rem 1.1rem 1.25rem;
+  display: flex;
+  flex-direction: column;
+  gap: .35rem;
+  flex: 1;
+}
+.product-category {
+  font-size: .6875rem;
+  font-weight: 600;
+  letter-spacing: .07em;
+  text-transform: uppercase;
+  color: var(--color-text-muted);
+}
+.product-name {
+  font-size: 1rem;
+  font-weight: 600;
+  letter-spacing: -.01em;
+  color: var(--color-text);
+  display: -webkit-box;
+  -webkit-box-orient: vertical;
+  -webkit-line-clamp: 2;
+  overflow: hidden;
+}
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .35rem;
+  font-size: .8125rem;
+}
+.stars { color: #f5a623; letter-spacing: .04em; }
+.rating-count { color: var(--color-text-muted); }
+
+.product-pricing {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+  margin-top: auto;
+  padding-top: .5rem;
+}
+.price-current {
+  font-size: 1.1875rem;
+  font-weight: 700;
+  letter-spacing: -.02em;
+}
+.price-original {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.price-discount {
+  font-size: .75rem;
+  font-weight: 700;
+  color: var(--color-success);
+  background: rgba(15,157,88,.1);
+  padding: .15rem .45rem;
+  border-radius: var(--radius-full);
+}
+
+.btn-add-cart {
+  margin-top: .75rem;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: .5rem;
+  width: 100%;
+  padding: .65rem 1rem;
+  background: var(--color-brand);
+  color: #fff;
+  border: none;
+  border-radius: var(--radius-md);
+  font-size: .9rem;
+  font-weight: 600;
+  transition: background var(--transition), box-shadow var(--transition), transform var(--transition);
+}
+.btn-add-cart:hover  { background: #2a2a4a; box-shadow: 0 4px 16px rgba(26,26,46,.3); }
+.btn-add-cart:active { transform: scale(.97); }
+.btn-add-cart:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
+.btn-add-cart.added  { background: var(--color-success); }
+
+/* ─── Deals Section ──────────────────────────────────────────── */
+.deals-section {
+  padding-block: clamp(40px, 6vw, 72px);
+  background: var(--color-surface-2);
+}
+
+.deals-header {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+  flex-wrap: wrap;
+  margin-bottom: 1.75rem;
+}
+.deals-header h2 {
+  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
+  font-weight: 700;
+  letter-spacing: -.02em;
+}
+.countdown {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-left: auto;
+}
+.countdown-label {
+  font-size: .8125rem;
+  font-weight: 600;
+  color: var(--color-text-muted);
+}
+.countdown-timer {
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+}
+.countdown-unit {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  min-width: 40px;
+  background: var(--color-brand);
+  color: #fff;
+  border-radius: var(--radius-sm);
+  padding: .35rem .5rem;
+}
+.countdown-num {
+  font-size: 1.1rem;
+  font-weight: 700;
+  letter-spacing: -.02em;
+  line-height: 1;
+}
+.countdown-sep {
+  font-size: 1.1rem;
+  font-weight: 700;
+  color: var(--color-text-muted);
+}
+.countdown-lbl {
+  font-size: .55rem;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  opacity: .75;
+  margin-top: .1rem;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr));
+  gap: var(--gap);
+}
+
+.deal-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  gap: 1rem;
+  padding: 1.25rem;
+  box-shadow: var(--shadow-card);
+  border: 1px solid var(--color-border);
+  transition: box-shadow var(--transition), transform var(--transition);
+  align-items: center;
+}
+.deal-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-2px); }
+
+.deal-image {
+  flex-shrink: 0;
+  width: 90px; height: 90px;
+  background: var(--color-surface-2);
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  font-size: 2.5rem;
+}
+.deal-info { flex: 1; min-width: 0; }
+.deal-category {
+  font-size: .6875rem;
+  font-weight: 600;
+  letter-spacing: .07em;
+  text-transform: uppercase;
+  color: var(--color-deal);
+  margin-bottom: .2rem;
+}
+.deal-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  margin-bottom: .35rem;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.deal-progress {
+  margin-bottom: .5rem;
+}
+.progress-bar {
+  height: 5px;
+  background: var(--color-surface-3);
+  border-radius: var(--radius-full);
+  overflow: hidden;
+  margin-bottom: .3rem;
+}
+.progress-fill {
+  height: 100%;
+  background: var(--color-deal);
+  border-radius: var(--radius-full);
+  transition: width 1s ease;
+}
+.progress-label { font-size: .7rem; color: var(--color-text-muted); }
+.deal-pricing {
+  display: flex;
+  align-items: baseline;
+  gap: .5rem;
+}
+.deal-price {
+  font-size: 1.2rem;
+  font-weight: 800;
+  color: var(--color-accent);
+}
+.deal-original {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.deal-save {
+  font-size: .75rem;
+  font-weight: 700;
+  color: var(--color-success);
+}
+
+/* ─── Banner Strip ───────────────────────────────────────────── */
+.promo-banner {
+  background: var(--color-accent);
+  color: #fff;
+  padding-block: 1rem;
+}
+.promo-inner {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: 1.5rem;
+  flex-wrap: wrap;
+  text-align: center;
+}
+.promo-item {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  font-size: .9rem;
+  font-weight: 500;
+}
+.promo-item strong { font-weight: 700; }
+.promo-divider { opacity: .4; }
+
+/* ─── Editorial / Blog ───────────────────────────────────────── */
+.editorial-section { padding-block: clamp(40px, 6vw, 72px); }
+
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr 1fr;
+  gap: var(--gap);
+}
+.editorial-grid .card-featured {
+  grid-column: 1 / 3;
+}
+
+@media (max-width: 900px) {
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .editorial-grid .card-featured { grid-column: 1 / -1; }
+}
+@media (max-width: 600px) {
+  .editorial-grid { grid-template-columns: 1fr; }
+}
+
+.editorial-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  box-shadow: var(--shadow-card);
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.editorial-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-3px); }
+
+.editorial-card-img {
+  aspect-ratio: 16/9;
+  background: linear-gradient(135deg, var(--color-brand) 0%, #0f3460 100%);
+  display: grid;
+  place-items: center;
+  font-size: 3.5rem;
+  overflow: hidden;
+  position: relative;
+}
+.card-featured .editorial-card-img { aspect-ratio: 21/9; font-size: 5rem; }
+
+.editorial-tag {
+  position: absolute;
+  top: .75rem; left: .75rem;
+  padding: .25rem .65rem;
+  background: rgba(0,0,0,.55);
+  color: #fff;
+  font-size: .7rem;
+  font-weight: 700;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  border-radius: var(--radius-full);
+  backdrop-filter: blur(4px);
+}
+
+.editorial-body {
+  padding: 1.25rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+}
+.editorial-meta {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+}
+.editorial-dot { opacity: .4; }
+.editorial-title {
+  font-size: 1.05rem;
+  font-weight: 700;
+  letter-spacing: -.015em;
+  line-height: 1.3;
+}
+.card-featured .editorial-title { font-size: clamp(1.1rem, 2vw, 1.35rem); }
+.editorial-excerpt {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  display: -webkit-box;
+  -webkit-box-orient: vertical;
+  -webkit-line-clamp: 2;
+  overflow: hidden;
+  line-height: 1.55;
+}
+.editorial-link {
+  margin-top: auto;
+  padding-top: .75rem;
+  font-size: .875rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  display: inline-flex;
+  align-items: center;
+  gap: .25rem;
+  border-radius: var(--radius-sm);
+  transition: gap var(--transition), color var(--transition);
+}
+.editorial-link:hover { gap: .5rem; color: var(--color-accent-hover); }
+.editorial-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
+
+/* ─── Newsletter ─────────────────────────────────────────────── */
+.newsletter-section {
+  padding-block: clamp(40px, 6vw, 72px);
+  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
+  color: #fff;
+  text-align: center;
+}
+.newsletter-inner { max-width: 560px; margin-inline: auto; }
+.newsletter-icon { font-size: 2.5rem; margin-bottom: .75rem; }
+.newsletter-section h2 {
+  font-size: clamp(1.5rem, 3vw, 2rem);
+  font-weight: 800;
+  letter-spacing: -.03em;
+  margin-bottom: .75rem;
+}
+.newsletter-section p {
+  color: rgba(255,255,255,.65);
+  margin-bottom: 1.75rem;
+  font-size: 1rem;
+}
+.newsletter-form {
+  display: flex;
+  gap: .5rem;
+  max-width: 440px;
+  margin-inline: auto;
+  flex-wrap: wrap;
+}
+.newsletter-input {
+  flex: 1;
+  min-width: 200px;
+  height: 48px;
+  padding: 0 1.1rem;
+  border: 1.5px solid rgba(255,255,255,.2);
