+.newsletter-input:focus {
+  outline: none;
+  border-color: var(--color-accent);
+  background: rgba(255,255,255,.12);
+  box-shadow: 0 0 0 3px rgba(233,69,96,.25);
+}
+.newsletter-btn {
+  height: 48px;
+  padding: 0 1.5rem;
+  background: var(--color-accent);
+  color: #fff;
+  border: none;
+  border-radius: var(--radius-full);
+  font-size: .9375rem;
+  font-weight: 600;
+  white-space: nowrap;
+  transition: background var(--transition), box-shadow var(--transition);
+}
+.newsletter-btn:hover { background: var(--color-accent-hover); box-shadow: 0 4px 16px rgba(233,69,96,.4); }
+.newsletter-btn:focus-visible { outline: 2px solid #fff; outline-offset: 3px; }
+.newsletter-privacy { font-size: .75rem; color: rgba(255,255,255,.4); margin-top: .75rem; }
+
+/* Status message */
+.status-msg {
+  margin-top: .75rem;
+  font-size: .875rem;
+  font-weight: 500;
+  min-height: 1.25em;
+  color: rgba(255,255,255,.9);
+}
+
+/* ─── Cart Drawer ────────────────────────────────────────────── */
+.cart-overlay {
+  position: fixed;
+  inset: 0;
+  background: rgba(0,0,0,.4);
+  z-index: 200;
+  opacity: 0;
+  pointer-events: none;
+  transition: opacity var(--transition);
+}
+.cart-overlay.open { opacity: 1; pointer-events: auto; }
+
+.cart-drawer {
+  position: fixed;
+  top: 0; right: 0; bottom: 0;
+  width: min(400px, 100vw);
+  background: var(--color-surface);
+  z-index: 201;
+  display: flex;
+  flex-direction: column;
+  transform: translateX(100%);
+  transition: transform 280ms cubic-bezier(.4,0,.2,1);
+  box-shadow: -8px 0 40px rgba(0,0,0,.15);
+}
+.cart-drawer.open { transform: translateX(0); }
+
+.cart-header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 1.25rem 1.5rem;
+  border-bottom: 1px solid var(--color-border);
