      excerpt: 'Discover how intentional choices in your home and wardrobe can lead to a more fulfilling, clutter-free lifestyle — and the products that help you get there.',
      author: 'Maya Chen', date: 'May 2, 2025', readTime: '6 min',
    },
    {
      id: 'a2', featured: false,
      tag: 'Tech',
      emoji: '🎧',
      gradient: 'linear-gradient(135deg,#0f3460 0%,#16213e 100%)',
      title: 'Best Wireless Headphones for Every Budget',
      excerpt: 'From premium over-ears to affordable earbuds, we tested 20+ models to find the best picks.',
      author: 'James Park', date: 'Apr 28, 2025', readTime: '4 min',
    },
    {
      id: 'a3', featured: false,
      tag: 'Home',
      emoji: '🏡',
      gradient: 'linear-gradient(135deg,#16213e 0%,#0f9d58 100%)',
      title: '10 Small Home Upgrades That Make a Big Difference',
      excerpt: 'Refresh your space with affordable swaps that have massive visual impact.',
      author: 'Sofia Reyes', date: 'Apr 20, 2025', readTime: '5 min',
    },
  ];

  /* ── Cart State ─────────────────────────────────────────────── */
  const cart = [];

  function cartTotal() {
    return cart.reduce((s, i) => s + i.price, 0);
  }

  function updateCartBadge() {
    const badge = document.getElementById('cart-count');
    if (badge) {
      badge.textContent = cart.length;
      badge.hidden = cart.length === 0;
    }
  }

  function addToCart(product) {
    cart.push({ ...product });
    updateCartBadge();
    renderCartItems();
    showToast(`${product.name} added to cart`);
  }

  function removeFromCart(id) {
    const idx = cart.findIndex(i => i.id === id);
    if (idx !== -1) cart.splice(idx, 1);
    updateCartBadge();
    renderCartItems();
  }

  /* ── Render Helpers ─────────────────────────────────────────── */
  function stars(rating) {
    const full  = Math.floor(rating);
    const half  = rating - full >= 0.5 ? 1 : 0;
    const empty = 5 - full - half;
    return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
  }

  function discount(original, current) {
    return Math.round((1 - current / original) * 100);
  }

  function fmt(n) {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n);
  }

  /* ── Render Products ────────────────────────────────────────── */
  function renderProducts() {
    const grid = document.getElementById('products-grid');
    if (!grid) return;

    grid.innerHTML = PRODUCTS.map(p => {
      const hasSale = p.originalPrice !== null;
      const pct     = hasSale ? discount(p.originalPrice, p.price) : 0;

      return `
        <li>
          <article class="product-card" aria-label="${p.name}">
            <div class="product-image-wrap">
              <div class="product-emoji" aria-hidden="true">${p.emoji}</div>
