  ];

  /* ── Cart State ─────────────────────────────────────────────── */
  const cart = [];

  function cartTotal() {
    return cart.reduce((s, i) => s + i.price, 0);
  }

  function updateCartBadge() {
    const badge = document.getElementById('cart-count');
    if (badge) {
      badge.textContent = cart.length;
      badge.hidden = cart.length === 0;
    }
  }

  function addToCart(product) {
    cart.push({ ...product });
    updateCartBadge();
    renderCartItems();
    showToast(`${product.name} added to cart`);
  }

  function removeFromCart(id) {
    const idx = cart.findIndex(i => i.id === id);
    if (idx !== -1) cart.splice(idx, 1);
    updateCartBadge();
    renderCartItems();
  }

  /* ── Render Helpers ─────────────────────────────────────────── */
  function stars(rating) {
    const full  = Math.floor(rating);
    const half  = rating - full >= 0.5 ? 1 : 0;
    const empty = 5 - full - half;
    return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
  }

  function discount(original, current) {
    return Math.round((1 - current / original) * 100);
  }

  function fmt(n) {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n);
  }

  /* ── Render Products ────────────────────────────────────────── */
  function renderProducts() {
    const grid = document.getElementById('products-grid');
    if (!grid) return;

    grid.innerHTML = PRODUCTS.map(p => {
      const hasSale = p.originalPrice !== null;
      const pct     = hasSale ? discount(p.originalPrice, p.price) : 0;

      return `
        <li>
          <article class="product-card" aria-label="${p.name}">
            <div class="product-image-wrap">
              <div class="product-emoji" aria-hidden="true">${p.emoji}</div>
              ${p.badge ? `<span class="product-badge badge-${p.badge}" aria-label="${p.badge} item">${p.badge.charAt(0).toUpperCase() + p.badge.slice(1)}</span>` : ''}
              <button class="product-wishlist" aria-pressed="false" aria-label="Save ${p.name} to wishlist">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
              </button>
            </div>
            <div class="product-info">
              <p class="product-category">${p.category}</p>
              <h3 class="product-name">${p.name}</h3>
              <div class="product-rating">
                <span class="stars" aria-hidden="true">${stars(p.rating)}</span>
                <span class="visually-hidden">${p.rating} out of 5 stars,</span>
                <span class="rating-count">(${p.reviews.toLocaleString()})</span>
              </div>
              <div class="product-pricing">
                <span class="price-current">${fmt(p.price)}</span>
                ${hasSale ? `<span class="price-original" aria-label="Original price ${fmt(p.originalPrice)}">${fmt(p.originalPrice)}</span><span class="price-discount" aria-label="${pct}% off">-${pct}%</span>` : ''}
              </div>
              <button class="btn-add-cart" data-id="${p.id}" aria-label="Add ${p.name} to cart">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg>
                Add to Cart
              </button>
            </div>
          </article>
        </li>`;
    }).join('');

    /* Wishlist toggles */
    grid.querySelectorAll('.product-wishlist').forEach(btn => {
      btn.addEventListener('click', () => {
        const pressed = btn.getAttribute('aria-pressed') === 'true';
        btn.setAttribute('aria-pressed', String(!pressed));
        const name = btn.getAttribute('aria-label').replace(/^Save |^Remove | from wishlist$/g, '').trim();
        btn.setAttribute('aria-label', pressed ? `Save ${name} to wishlist` : `Remove ${name} from wishlist`);
        showToast(pressed ? 'Removed from wishlist' : 'Saved to wishlist');
      });
    });

    /* Add to cart buttons */
    grid.querySelectorAll('.btn-add-cart').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = Number(btn.dataset.id);
        const product = PRODUCTS.find(p => p.id === id);
        if (!product) return;
        btn.classList.add('added');
        btn.textContent = '✓ Added';
        setTimeout(() => {
          btn.classList.remove('added');
          btn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"/></svg> Add to Cart`;
        }, 1800);
        addToCart(product);
        openCart();
      });
    });
  }

  /* ── Render Deals ───────────────────────────────────────────── */
  function renderDeals() {
    const grid = document.getElementById('deals-grid');
    if (!grid) return;

    grid.innerHTML = DEALS.map(d => {
      const pct = discount(d.originalPrice, d.price);
      return `
        <li>
          <article class="deal-card" aria-label="${d.name} deal">
            <div class="deal-image" aria-hidden="true">${d.emoji}</div>
            <div class="deal-info">
              <p class="deal-category">${d.category}</p>
              <h3 class="deal-name">${d.name}</h3>
              <div class="deal-progress">
                <div class="progress-bar" role="progressbar" aria-valuenow="${d.sold}" aria-valuemin="0" aria-valuemax="100" aria-label="${d.sold}% sold">
                  <div class="progress-fill" style="width:${d.sold}%"></div>
                </div>
                <p class="progress-label">${d.sold}% claimed</p>
              </div>
              <div class="deal-pricing">
                <span class="deal-price">${fmt(d.price)}</span>
                <span class="deal-original" aria-label="Was ${fmt(d.originalPrice)}">${fmt(d.originalPrice)}</span>
                <span class="deal-save" aria-label="Save ${pct}%">Save ${pct}%</span>
              </div>
            </div>
          </article>
        </li>`;
    }).join('');
  }

  /* ── Render Editorial ───────────────────────────────────────── */
  function renderEditorial() {
    const grid = document.getElementById('editorial-grid');
    if (!grid) return;

    grid.innerHTML = ARTICLES.map(a => `
      <li${a.featured ? ' class="card-featured"' : ''}>
        <article class="editorial-card${a.featured ? ' card-featured' : ''}" aria-label="${a.title}">
          <div class="editorial-card-img" style="background:${a.gradient}" role="img" aria-label="${a.tag} article illustration">
            <span aria-hidden="true">${a.emoji}</span>
            <span class="editorial-tag">${a.tag}</span>
          </div>
          <div class="editorial-body">
            <div class="editorial-meta" aria-label="By ${a.author}, ${a.date}, ${a.readTime} read">
              <span>${a.author}</span>
              <span class="editorial-dot" aria-hidden="true">·</span>
              <time datetime="${a.date}">${a.date}</time>
              <span class="editorial-dot" aria-hidden="true">·</span>
              <span>${a.readTime} read</span>
            </div>
            <h3 class="editorial-title">${a.title}</h3>
            <p class="editorial-excerpt">${a.excerpt}</p>
            <a href="#" class="editorial-link" aria-label="Read full article: ${a.title}">
              Read article
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
            </a>
          </div>
        </article>
      </li>`).join('');
  }

  /* ── Render Cart Items ──────────────────────────────────────── */
  function renderCartItems() {
    const body  = document.getElementById('cart-items');
    const total = document.getElementById('cart-total-amount');
    const empty = document.getElementById('cart-empty');
    const list  = document.getElementById('cart-item-list');
    if (!body) return;

    if (cart.length === 0) {
      if (empty) empty.hidden = false;
      if (list)  list.hidden  = true;
    } else {
      if (empty) empty.hidden = true;
      if (list)  list.hidden  = false;
      list.innerHTML = cart.map((item, idx) => `
        <li class="cart-item">
          <div class="cart-item-img" aria-hidden="true">${item.emoji}</div>
          <div class="cart-item-info">
            <p class="cart-item-name">${item.name}</p>
            <p class="cart-item-price">${fmt(item.price)}</p>
          </div>
          <button class="cart-item-remove" data-idx="${idx}" aria-label="Remove ${item.name} from cart">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </li>`).join('');

      list.querySelectorAll('.cart-item-remove').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = Number(btn.dataset.idx);
          removeFromCart(cart[idx]?.id);
        });
      });
    }

    if (total) total.textContent = fmt(cartTotal());
  }

  /* ── Cart Drawer ────────────────────────────────────────────── */
  const cartOverlay = document.getElementById('cart-overlay');
  const cartDrawer  = document.getElementById('cart-drawer');
  let lastFocus = null;

  function openCart() {
    lastFocus = document.activeElement;
    cartOverlay?.classList.add('open');
    cartDrawer?.classList.add('open');
    cartDrawer?.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
    document.getElementById('cart-close')?.focus();
    renderCartItems();
  }

  function closeCart() {
    cartOverlay?.classList.remove('open');
    cartDrawer?.classList.remove('open');
    cartDrawer?.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    lastFocus?.focus();
  }

  document.getElementById('cart-btn')?.addEventListener('click', openCart);
  document.getElementById('cart-close')?.addEventListener('click', closeCart);
  cartOverlay?.addEventListener('click', closeCart);

  /* Trap focus inside cart drawer */
  cartDrawer?.addEventListener('keydown', e => {
    if (e.key === 'Escape') { closeCart(); return; }
    if (e.key !== 'Tab') return;
    const focusable = [...cartDrawer.querySelectorAll('button, a, input, [tabindex]:not([tabindex="-1"])')].filter(el => !el.hidden && el.offsetParent !== null);
    if (!focusable.length) return;
    const first = focusable[0], last = focusable[focusable.length - 1];
    if (e.shiftKey) { if (document.activeElement === first) { last.focus(); e.preventDefault(); } }
    else            { if (document.activeElement === last)  { first.focus(); e.preventDefault(); } }
  });

  /* ── Countdown Timer ────────────────────────────────────────── */
  function initCountdown() {
    const end = new Date(Date.now() + 6 * 3600000 + 23 * 60000 + 45000);

    function tick() {
      const diff = end - Date.now();
      if (diff <= 0) return;
      const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
      const m = String(Math.floor((diff % 3600000) / 60000)).padStart(2, '0');
      const s = String(Math.floor((diff % 60000) / 1000)).padStart(2, '0');

      const [elH, elM, elS] = ['countdown-h','countdown-m','countdown-s'].map(id => document.getElementById(id));
      if (elH) elH.textContent = h;
      if (elM) elM.textContent = m;
      if (elS) elS.textContent = s;

      /* Keep live region updated for screen readers every minute */
      const live = document.getElementById('countdown-live');
      if (live && s === '00') live.textContent = `${h} hours and ${m} minutes remaining in flash sale`;
    }
    tick();
    setInterval(tick, 1000);
  }

  /* ── Mobile menu ────────────────────────────────────────────── */
  function initMobileMenu() {
    const toggle = document.getElementById('menu-toggle');
    const nav    = document.getElementById('main-nav');
    if (!toggle || !nav) return;

    toggle.addEventListener('click', () => {
      const open = nav.classList.toggle('open');
      toggle.setAttribute('aria-expanded', String(open));
      toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    });

    /* Close on outside click */
    document.addEventListener('click', e => {
      if (!toggle.contains(e.target) && !nav.contains(e.target)) {
        nav.classList.remove('open');
        toggle.setAttribute('aria-expanded', 'false');
        toggle.setAttribute('aria-label', 'Open menu');
      }
    });

    /* Close on Escape */
    nav.addEventListener('keydown', e => {
      if (e.key === 'Escape') {
        nav.classList.remove('open');
        toggle.setAttribute('aria-expanded', 'false');
        toggle.focus();
      }
    });
  }

  /* ── Category filter ────────────────────────────────────────── */
  function initCategoryFilter() {
    document.querySelectorAll('.category-pill').forEach(pill => {
      pill.addEventListener('click', () => {
        document.querySelectorAll('.category-pill').forEach(p => p.setAttribute('aria-current', 'false'));
        pill.setAttribute('aria-current', 'true');
      });
    });
  }

  /* ── Newsletter ─────────────────────────────────────────────── */
  function initNewsletter() {
    const form   = document.getElementById('newsletter-form');
    const input  = document.getElementById('newsletter-email');
    const status = document.getElementById('newsletter-status');
    if (!form || !input || !status) return;

    form.addEventListener('submit', e => {
      e.preventDefault();
      const val = input.value.trim();
      if (!val || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)) {
        input.setAttribute('aria-invalid', 'true');
        status.textContent = 'Please enter a valid email address.';
        input.focus();
        return;
      }
      input.setAttribute('aria-invalid', 'false');
      status.textContent = '🎉 Thanks! You\'re subscribed.';
      input.value = '';
    });

    input.addEventListener('input', () => {
      if (input.getAttribute('aria-invalid') === 'true') {
        input.setAttribute('aria-invalid', 'false');
        status.textContent = '';
      }
    });
  }

  /* ── Toast ──────────────────────────────────────────────────── */
  function showToast(msg) {
    const region = document.getElementById('toast-region');
    if (!region) return;
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = msg;
    toast.setAttribute('role', 'status');
    region.appendChild(toast);
    setTimeout(() => {
      toast.classList.add('out');
      toast.addEventListener('animationend', () => toast.remove(), { once: true });
    }, 2800);
  }

  /* ── Search ─────────────────────────────────────────────────── */
  function initSearch() {
    const form  = document.getElementById('search-form');
    const input = document.getElementById('search-input');
    if (!form || !input) return;
    form.addEventListener('submit', e => {
      e.preventDefault();
      const q = input.value.trim();
      if (q) showToast(`Searching for "${q}"…`);
    });
  }

  /* ── Init ───────────────────────────────────────────────────── */
  function init() {
    renderProducts();
    renderDeals();
    renderEditorial();
    renderCartItems();
    initCountdown();
    initMobileMenu();
    initCategoryFilter();
    initNewsletter();
    initSearch();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
